create or replace function public.create_order_atomic(p_customer_id uuid,p_items jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare v_order_id uuid:=gen_random_uuid(); item jsonb; v public.product_variants; qty integer; unit numeric(12,2); cost numeric(12,2); total numeric(12,2):=0; begin if auth.uid() is null or public.current_role() not in('ADMIN','WAREHOUSE_MANAGER') then raise exception 'not authorized';end if;if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'items required';end if;insert into public.orders(id,customer_id,status,total,created_by) values(v_order_id,p_customer_id,'pending',0,auth.uid());for item in select * from jsonb_array_elements(p_items) loop qty:=(item->>'quantity')::integer;if qty<=0 then raise exception 'quantity must be positive';end if;select * into v from public.product_variants where id=(item->>'variant_id')::uuid for update;if not found or v.quantity<qty then raise exception 'insufficient stock for item';end if;unit:=v.selling_price;cost:=v.cost_price;total:=total+(unit*qty);perform set_config('app.inventory_rpc','on',true);update public.product_variants set quantity=quantity-qty,updated_at=now() where id=v.id;insert into public.inventory_movements(variant_id,type,quantity,reference_id,created_by,note) values(v.id,'reserved',qty,v_order_id,auth.uid(),'Order reservation');insert into public.order_items(order_id,variant_id,quantity,unit_price,cost_price) values(v_order_id,v.id,qty,unit,cost);end loop;update public.orders set total=total,updated_at=now() where id=v_order_id;insert into public.audit_logs(actor_id,action,entity_type,entity_id,after_data) values(auth.uid(),'order.created','orders',v_order_id,jsonb_build_object('total',total));insert into public.notifications(type,title,message,metadata) values('NEW_ORDER','New order',format('Order %s created',v_order_id),jsonb_build_object('order_id',v_order_id));return v_order_id;end; $$;grant execute on function public.create_order_atomic(uuid,jsonb) to authenticated;
create or replace view public.product_profitability as select p.id product_id,p.name,sum(oi.quantity) units_sold,sum(oi.line_total) revenue,sum(oi.quantity*oi.cost_price) cost,sum(oi.quantity*(oi.unit_price-oi.cost_price)) profit from public.products p join public.product_variants v on v.product_id=p.id join public.order_items oi on oi.variant_id=v.id join public.orders o on o.id=oi.order_id where o.status in('confirmed','processing','shipped','delivered') group by p.id,p.name;
create or replace view public.inventory_summary as select count(*)::bigint sku_count,coalesce(sum(quantity),0)::bigint total_units,coalesce(sum(quantity*cost_price),0)::numeric(12,2) inventory_value,count(*) filter(where quantity=0)::bigint out_of_stock,count(*) filter(where quantity>0 and quantity<=minimum_quantity)::bigint low_stock from public.product_variants;